/* v0.11: specification stock; original inventory tables remain untouched. */
const SimpleInventory=(()=>{
 const I=typeof module!=='undefined'?require('./data.js'):Inventory,key='simpleInventory',norm=s=>String(s??'').trim().replace(/\s+/g,'').toLowerCase(),id=()=>crypto.randomUUID(),now=()=>new Date().toISOString(),clone=x=>structuredClone(x),qty=n=>Number.isSafeInteger(n)&&n>=0&&n<=999999999;
 const text=(s,max=100)=>typeof s==='string'&&s.length<=max;
 const get=db=>I.transaction(db,['meta'],tx=>I.request(tx.objectStore('meta').get(key)),'readonly');
 const stateKey=s=>JSON.stringify(s),validIcon=k=>typeof k==='string'&&/^[a-z][a-z0-9-]{0,39}$/.test(k);
 const itemFor=(s,v)=>s.items.find(i=>i.id===s.brands.find(b=>b.id===v.brandId)?.itemId);
 function validate(s){if(!s||s.id!==key||s.version!==1)throw Error('简化库存格式无效');const maps={};for(const table of ['items','brands','variants','operations']){if(!Array.isArray(s[table])||s[table].length>100000)throw Error('库存表缺失或过大');maps[table]=new Map();for(const row of s[table]){if(!text(row.id,200)||!row.id||maps[table].has(row.id))throw Error('记录 ID 无效或重复');maps[table].set(row.id,row);}}
  const unique=new Set();for(const i of s.items){if(!text(i.name)||!norm(i.name)||!text(i.unit,20)||!norm(i.unit)||!qty(i.minStock)||typeof i.reminderEnabled!=='boolean')throw Error('品类档案无效');if(i.archived!=null&&typeof i.archived!=='boolean'||i.icon!=null&&!validIcon(i.icon))throw Error('归档或图标设置无效');const k=norm(i.name);if(unique.has(k))throw Error('品类重名');unique.add(k);}
  for(const [table,parent,fk] of [['brands','items','itemId'],['variants','brands','brandId']]){const seen=new Set();for(const r of s[table]){const k=r[fk]+'|'+norm(r.name);if(!maps[parent].has(r[fk])||!text(r.name)||!norm(r.name)||seen.has(k))throw Error('品牌或规格重名或关联无效');seen.add(k);}}
  const balances=new Map(),stockRevs=new Map(),lastStock=new Map();for(const v of s.variants){if(!qty(v.quantity)||!qty(v.baseQuantity)||!qty(v.revision)||!qty(v.stockRevision)||!text(v.location,5000)||v.revision<v.stockRevision||typeof v.hidden!=='boolean'||v.hidden&&v.quantity!==0)throw Error('规格库存无效');balances.set(v.id,v.baseQuantity);}
  for(const o of s.operations){if(!o.label||!text(o.label.item)||!norm(o.label.item))throw Error('操作名称缺失');if(!['IN','OUT','REVERSE','EDIT','ITEM_EDIT','MINIMUM','DELETE','CREATE','ARCHIVE','UNARCHIVE','ICON'].includes(o.type)||!text(o.at,100)||isNaN(Date.parse(o.at)))throw Error('操作类型或时间无效');if(['ITEM_EDIT','MINIMUM','ARCHIVE','UNARCHIVE','ICON'].includes(o.type)){if(!maps.items.has(o.itemId))throw Error('操作品类不存在');}else if(!maps.variants.has(o.variantId))throw Error('操作规格不存在');if(['IN','OUT','REVERSE','DELETE'].includes(o.type)){if(!Number.isSafeInteger(o.delta)||!qty(o.beforeQuantity)||!qty(o.afterQuantity)||o.afterQuantity-o.beforeQuantity!==o.delta||!qty(o.stockRevision)||(o.type==='IN'&&o.delta<=0)||(o.type==='OUT'&&o.delta>=0)||(o.type==='DELETE'&&(o.delta>0||o.afterQuantity!==0)))throw Error('数量流水无效');if(o.beforeQuantity!==balances.get(o.variantId)||o.stockRevision!==(stockRevs.get(o.variantId)||0)+1)throw Error('流水顺序或修订号不一致');balances.set(o.variantId,o.afterQuantity);stockRevs.set(o.variantId,o.stockRevision);lastStock.set(o.variantId,o.type);}
   if(['ARCHIVE','UNARCHIVE'].includes(o.type)&&(typeof o.before!=='boolean'||typeof o.after!=='boolean'||o.before===o.after||o.after!==(o.type==='ARCHIVE')))throw Error('归档流水无效');if(o.type==='ICON'&&(!validIcon(o.before)||!validIcon(o.after)))throw Error('图标流水无效');if(o.type==='REVERSE'){const original=maps.operations.get(o.originalOperationId);if(!original||!['IN','OUT'].includes(original.type)||original.reversedBy!==o.id||original.variantId!==o.variantId||o.delta!==-original.delta)throw Error('撤销关联无效');}if(o.reversedBy){const r=maps.operations.get(o.reversedBy);if(!r||r.type!=='REVERSE'||r.originalOperationId!==o.id)throw Error('撤销记录缺失');}}
  if(s.preferences!=null&&(!s.preferences||!['grid','list'].includes(s.preferences.view)))throw Error('库存视图设置无效');for(const v of s.variants)if(balances.get(v.id)!==v.quantity||(stockRevs.get(v.id)||0)!==v.stockRevision||v.hidden!==(lastStock.get(v.id)==='DELETE'))throw Error('库存数量与流水不一致');if(!s.legacyArchive)throw Error('旧数据归档缺失');I.validate(s.legacyArchive);return s;
 }
 function convert(backup){const d=I.validate(backup),items=[],brands=[],variants=[];for(const v of d.variants){const rows=d.batches.filter(b=>b.variantId===v.id&&!I.isCancelledBatch(d,b));if(!rows.length)continue;const b=d.brands.find(b=>b.id===v.brandId),i=d.items.find(i=>i.id===b.itemId);if(!items.some(x=>x.id===i.id))items.push({id:i.id,name:i.name,unit:i.unit,minStock:i.minStock??1,reminderEnabled:i.reminderEnabled!==false});if(!brands.some(x=>x.id===b.id))brands.push({id:b.id,itemId:b.itemId,name:b.name});const quantity=rows.reduce((n,b)=>n+b.quantity,0);if(!qty(quantity))throw Error('合并后数量超出范围，请先核对库存');variants.push({id:v.id,brandId:v.brandId,name:v.name,quantity,baseQuantity:quantity,location:[...new Set(rows.map(b=>String(b.location||'').trim()).filter(Boolean))].join('\n'),revision:0,stockRevision:0,hidden:false});}
  const archive=clone(backup);archive.tables.meta=archive.tables.meta.filter(m=>m.id!==key);delete archive.integrity;const s={id:key,version:1,migratedAt:now(),items,brands,variants,operations:[],legacyArchive:archive};validate(s);return s;
 }
 function summary(s){return s.variants.filter(v=>!v.hidden).map(v=>{const b=s.brands.find(b=>b.id===v.brandId),i=s.items.find(i=>i.id===b.itemId);return {id:v.id,item:i.name,brand:b.name,spec:v.name,quantity:v.quantity,unit:i.unit,location:v.location,archived:!!i.archived,icon:i.icon||'auto'};});}
 async function preview(db){const backup=await I.rawSnapshot(db),state=convert(backup);return {state,rows:summary(state),expectedState:I.stateKey(backup.tables),before:backup.tables.batches.filter(b=>!I.isCancelledBatch(backup.tables,b)).length,archiveCount:backup.tables.batches.length};}
 async function migrate(db,expectedState){return I.transaction(db,[...I.tables,'recovery'],async tx=>{const d=Object.fromEntries(await Promise.all(I.tables.map(async t=>[t,await I.request(tx.objectStore(t).getAll())])));if(d.meta.some(m=>m.id===key))throw Error('已切换到简化库存，请刷新');if(I.stateKey(d)!==expectedState)throw Error('预览后库存已变化，请重新核对');const backup={format:'tuntun-backup',version:2,exportedAt:now(),tables:d},s=convert(backup);tx.objectStore('recovery').add({id:id(),at:now(),backup,kind:'before-simple-migration'});tx.objectStore('meta').put(s);return s;});}
 async function mutate(db,fn){return I.transaction(db,['meta'],async tx=>{const s=await I.request(tx.objectStore('meta').get(key));if(!s)throw Error('请先确认库存简化');validate(s);const result=fn(s);validate(s);tx.objectStore('meta').put(s);return result;});}
 async function ensure(db){let existing=await get(db);if(existing){validate(existing);return existing;}for(let attempt=0;attempt<2;attempt++){const p=await preview(db);try{return await migrate(db,p.expectedState);}catch(e){existing=await get(db);if(existing){validate(existing);return existing;}if(attempt===0&&e.message==='预览后库存已变化，请重新核对')continue;throw e;}}}
 function context(s,v){const b=s.brands.find(b=>b.id===v.brandId),i=s.items.find(i=>i.id===b.itemId);return {item:i.name,brand:b.name,spec:v.name,unit:i.unit};}
 function stockOp(s,v,type,delta,extra={}){const before=v.quantity,after=before+delta;if(!qty(after))throw Error('库存不足或数量超出范围');v.quantity=after;v.revision++;v.stockRevision++;const o={id:id(),type,variantId:v.id,at:now(),delta,beforeQuantity:before,afterQuantity:after,stockRevision:v.stockRevision,label:context(s,v),...extra};s.operations.push(o);return o;}
 function find(s,variantId){const v=s.variants.find(v=>v.id===variantId&&!v.hidden);if(!v)throw Error('规格已删除或不存在，请刷新');if(itemFor(s,v)?.archived)throw Error('产品已归档，请先取消归档');return v;}
 function expected(v,a){if(!a||a.revision!==v.revision||a.quantity!==v.quantity)throw Error('库存已变化，请重新打开后核对');}
 const change=(db,a)=>mutate(db,s=>{const v=find(s,a.variantId);if(!Number.isSafeInteger(a.delta)||!a.delta)throw Error('增减数量必须是非零整数');if(a.expected)expected(v,a.expected);return stockOp(s,v,a.delta>0?'IN':'OUT',a.delta);});
 const add=(db,a)=>mutate(db,s=>{const name=String(a.itemName||'').trim(),brand=String(a.brandName||'').trim()||'未指定品牌',spec=String(a.specName||'').trim()||'未指定规格',q=Number(a.quantity),location=String(a.location||'').trim(),icon=a.iconKey||'auto';if(!name||[name,brand,spec].some(x=>x.length>100)||!qty(q)||a.quantity==null||a.quantity===''||location.length>5000||!validIcon(icon))throw Error('请填写有效名称和非负整数数量');let i=s.items.find(i=>norm(i.name)===norm(name)),restored=null;if(i?.archived){if(!a.restoreArchived)throw Error('同名产品已归档，请明确确认恢复后继续');if(a.expectedItemState!==stateKey(i))throw Error('归档产品已变化，请重新核对');i.archived=false;restored={id:id(),type:'UNARCHIVE',itemId:i.id,at:now(),before:true,after:false,label:{item:i.name}};s.operations.push(restored);}if(!i){const unit=String(a.unit||'件').trim();if(!unit||unit.length>20)throw Error('计数单位无效');i={id:id(),name,unit,minStock:1,reminderEnabled:true,archived:false,icon};s.items.push(i);}let b=s.brands.find(b=>b.itemId===i.id&&norm(b.name)===norm(brand));if(!b){b={id:id(),itemId:i.id,name:brand};s.brands.push(b);}let v=s.variants.find(v=>v.brandId===b.id&&norm(v.name)===norm(spec)),created=!v;if(v?.hidden){if(q===0)throw Error('已删除的规格请以正数重新入库，或使用新规格');v.hidden=false;}if(!v){v={id:id(),brandId:b.id,name:spec,quantity:0,baseQuantity:0,location,revision:0,stockRevision:0,hidden:false};s.variants.push(v);}if(q>0)return stockOp(s,v,'IN',q);if(!created){if(restored)return restored;throw Error('该规格已存在，数量为零无需重复新增');}const op={id:id(),type:'CREATE',variantId:v.id,at:now(),label:context(s,v)};s.operations.push(op);return op;});
 const edit=(db,a)=>mutate(db,s=>{const v=find(s,a.variantId);expected(v,a.expected);const before={...context(s,v),location:v.location},oldBrand=s.brands.find(b=>b.id===v.brandId),brand=String(a.brandName||'').trim()||'未指定品牌',spec=String(a.specName||'').trim()||'未指定规格',location=String(a.location||'').trim();if(brand.length>100||spec.length>100||location.length>5000)throw Error('品牌、规格或位置过长');let b=s.brands.find(b=>b.itemId===oldBrand.itemId&&norm(b.name)===norm(brand));if(!b){b={id:id(),itemId:oldBrand.itemId,name:brand};s.brands.push(b);}if(s.variants.some(x=>x.id!==v.id&&x.brandId===b.id&&norm(x.name)===norm(spec)))throw Error('已有同名品牌规格，不能直接合并；请使用该规格增减');v.brandId=b.id;v.name=spec;v.location=location;v.revision++;const after={...context(s,v),location};if(JSON.stringify(before)===JSON.stringify(after))throw Error('信息未变化');const o={id:id(),type:'EDIT',variantId:v.id,at:now(),before,after,label:context(s,v)};s.operations.push(o);return o;});
 const editItem=(db,a)=>mutate(db,s=>{const i=s.items.find(i=>i.id===a.itemId);if(!i||stateKey(i)!==a.expectedState)throw Error('品类信息已变化，请重新打开');const name=String(a.name||'').trim();if(!name||name.length>100||s.items.some(x=>x.id!==i.id&&norm(x.name)===norm(name)))throw Error('名称为空、过长或与已有品类重名');if(i.name===name)throw Error('信息未变化');const before=i.name;i.name=name;const o={id:id(),type:'ITEM_EDIT',itemId:i.id,at:now(),before,after:name,label:{item:name}};s.operations.push(o);return o;});
 const minimum=(db,a)=>mutate(db,s=>{const i=s.items.find(i=>i.id===a.itemId);if(!i||!qty(a.value)||typeof a.enabled!=='boolean')throw Error('最低库存或提醒开关无效');const o={id:id(),type:'MINIMUM',itemId:i.id,at:now(),before:{value:i.minStock,enabled:i.reminderEnabled},after:{value:a.value,enabled:a.enabled},label:{item:i.name}};i.minStock=a.value;i.reminderEnabled=a.enabled;s.operations.push(o);return o;});
 const updateItem=(db,a)=>mutate(db,s=>{const i=s.items.find(i=>i.id===a.itemId),name=String(a.name||'').trim();if(!i||stateKey(i)!==a.expectedState)throw Error('品类信息已变化，请重新打开');if(!name||name.length>100||s.items.some(x=>x.id!==i.id&&norm(x.name)===norm(name))||!qty(a.value)||typeof a.enabled!=='boolean')throw Error('品类名称重名、为空或最低库存无效');if(a.iconKey!=null&&!validIcon(a.iconKey))throw Error('图标设置无效');if(a.iconKey!=null&&(i.icon||'auto')!==a.iconKey){s.operations.push({id:id(),type:'ICON',itemId:i.id,at:now(),before:i.icon||'auto',after:a.iconKey,label:{item:name}});i.icon=a.iconKey;}if(i.name!==name){s.operations.push({id:id(),type:'ITEM_EDIT',itemId:i.id,at:now(),before:i.name,after:name,label:{item:name}});i.name=name;}if(i.minStock!==a.value||i.reminderEnabled!==a.enabled){s.operations.push({id:id(),type:'MINIMUM',itemId:i.id,at:now(),before:{value:i.minStock,enabled:i.reminderEnabled},after:{value:a.value,enabled:a.enabled},label:{item:name}});i.minStock=a.value;i.reminderEnabled=a.enabled;}});
 function canUndo(s,opId){const o=s.operations.find(o=>o.id===opId),v=s.variants.find(v=>v.id===o?.variantId);return !!o&&['IN','OUT'].includes(o.type)&&!o.reversedBy&&!!v&&!v.hidden&&!itemFor(s,v)?.archived&&v.stockRevision===o.stockRevision&&qty(v.quantity-o.delta);}
 const archiveKey=(s,itemId)=>JSON.stringify(s.variants.filter(v=>s.brands.find(b=>b.id===v.brandId)?.itemId===itemId).map(v=>({id:v.id,quantity:v.quantity,revision:v.revision,hidden:v.hidden})));
 const archive=(db,a)=>mutate(db,s=>{const i=s.items.find(i=>i.id===a.itemId);if(!i||stateKey(i)!==a.expectedState)throw Error('产品信息已变化，请重新打开核对');if(a.expectedStockState!=null&&a.expectedStockState!==archiveKey(s,i.id))throw Error('确认后库存已变化，请重新核对');if(typeof a.archived!=='boolean'||!!i.archived===a.archived)throw Error('归档状态未变化');const op={id:id(),type:a.archived?'ARCHIVE':'UNARCHIVE',itemId:i.id,at:now(),before:!!i.archived,after:a.archived,label:{item:i.name}};i.archived=a.archived;s.operations.push(op);return op;});
 const setView=(db,view)=>mutate(db,s=>{if(!['grid','list'].includes(view))throw Error('视图无效');s.preferences={...s.preferences,view};});
 const undo=(db,opId)=>mutate(db,s=>{if(!canUndo(s,opId))throw Error('该记录已撤销或已有后续数量操作，不能撤销');const o=s.operations.find(o=>o.id===opId),v=find(s,o.variantId),r=stockOp(s,v,'REVERSE',0-o.delta,{originalOperationId:o.id});o.reversedBy=r.id;return r;});
 const remove=(db,a)=>mutate(db,s=>{const v=find(s,a.variantId);expected(v,a.expected);const o=stockOp(s,v,'DELETE',0-v.quantity);v.hidden=true;return o;});
 async function seal(obj){const safe=clone(obj);delete safe.integrity;const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(safe)))),x=>x.toString(16).padStart(2,'0')).join('');return {...safe,integrity:{algorithm:'SHA-256',digest}};}
 async function backup(db){const s=await get(db);validate(s);return seal({format:'tuntun-simple-backup',version:1,exportedAt:now(),state:s});}
 async function decode(obj){if(obj?.format==='tuntun-backup'){await I.verifyBackup(obj);const existing=obj.tables.meta.find(m=>m.id===key);if(existing){validate(existing);return clone(existing);}return convert(obj);}if(obj?.format!=='tuntun-simple-backup'||obj.version!==1)throw Error('不是有效库存备份');validate(obj.state);if(obj.integrity?.algorithm!=='SHA-256'||(await seal(obj)).integrity.digest!==obj.integrity.digest)throw Error('备份完整性校验失败');return clone(obj.state);}
 async function restore(db,obj,expectedState){const safe=clone(obj),s=await decode(safe);return I.transaction(db,['meta','recovery'],async tx=>{const old=await I.request(tx.objectStore('meta').get(key));if(stateKey(old)!==expectedState)throw Error('预览后库存已变化，请重新选择文件');if(old)tx.objectStore('recovery').add({id:id(),at:now(),simpleState:old,kind:'before-simple-restore'});tx.objectStore('meta').put(s);return s;});}
 return {get,ensure,archive,archiveKey,setView,validate,preview,migrate,convert,summary,context,stateKey,change,add,edit,editItem,minimum,updateItem,canUndo,undo,remove,backup,decode,restore,seal};
})();
if(typeof module!=='undefined')module.exports=SimpleInventory;
